def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i == n or line[i] == ',':
                            fields.append(field)
                            if i < n:
                                i += 1  # Skip the comma
                            break
                        else:
                            # Malformed: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Malformed: unquoted field contains a quote
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

